        return mountIndeterminateComponent(p144, p145, p145.type, p146)
    end

    if p145.tag == LazyComponent then
        return (mountLazyComponent(p144, p145, p145.elementType, lanes, p146))
    end

    if p145.tag == FunctionComponent then
        local type, pendingProps = p145.type, p145.pendingProps

        if p145.elementType ~= type then
            pendingProps = resolveDefaultProps(type, pendingProps)
        end

        return updateFunctionComponent(p144, p145, type, pendingProps, p146)
    end

    if p145.tag == ClassComponent then
        local type, pendingProps = p145.type, p145.pendingProps

        if p145.elementType ~= type or not pendingProps then
            pendingProps = resolveDefaultProps(type, pendingProps)
        end

        return (updateClassComponent(p144, p145, type, pendingProps, p146))
    end

    if p145.tag == HostRoot then
        return updateHostRoot(p144, p145, p146)
    end

    if p145.tag == HostComponent then
        return (updateHostComponent(p144, p145, p146))
    end

    if p145.tag == HostText then
        if p144 == nil then
            tryToClaimNextHydratableInstance(p145)
        end
    else
        if p145.tag == SuspenseComponent then
            return updateSuspenseComponent(p144, p145, p146)
        end

        if p145.tag == HostPortal then
            return updatePortalComponent(p144, p145, p146)
        end

        if p145.tag == ForwardRef then
            local type, pendingProps = p145.type, p145.pendingProps

            if p145.elementType ~= type then
                pendingProps = resolveDefaultProps(type, pendingProps)
            end

            return updateForwardRef(p144, p145, type, pendingProps, p146)
        end

        if p145.tag == Fragment then
            return updateFragment(p144, p145, p146)
        end

        if p145.tag == Mode then
            return updateMode(p144, p145, p146)
        end

        if p145.tag == Profiler then
            return updateProfiler(p144, p145, p146)
        end

        if p145.tag == ContextProvider then
            return updateContextProvider(p144, p145, p146)
        end

        if p145.tag == ContextConsumer then
            return updateContextConsumer(p144, p145, p146)
        end

        if p145.tag == MemoComponent then
            local _type = p145.type
            local v118 = resolveDefaultProps(_type, p145.pendingProps)
            local propTypes, validateProps

            if (__DEV__ or __DISABLE_ALL_WARNINGS_EXCEPT_PROP_VALIDATION__) and p145.type ~= p145.elementType then
                if type(_type) == "table" then
                    propTypes = _type.propTypes
                    validateProps = _type.validateProps
                end

                if propTypes or validateProps then
                    checkPropTypes(propTypes, validateProps, v118, "prop", getComponentName(_type))
                end
            end

            return updateMemoComponent(p144, p145, _type, resolveDefaultProps(_type.type, v118), lanes, p146)
        end

        if p145.tag == SimpleMemoComponent then
            return updateSimpleMemoComponent(p144, p145, p145.type, p145.pendingProps, lanes, p146)
        end

        if p145.tag == IncompleteClassComponent then
            local type, pendingProps = p145.type, p145.pendingProps

            if p145.elementType ~= type or not pendingProps then
                pendingProps = resolveDefaultProps(type, pendingProps)
            end

            return mountIncompleteClassComponent(p144, p145, type, pendingProps, p146)
        end

        if p145.tag == OffscreenComponent or p145.tag == LegacyHiddenComponent then
            return (updateOffscreenComponent(p144, p145, p146))
        end

        invariant(false, "Unknown unit of work tag (%s). This error is likely caused by a bug in React. Please file an issue.", (tostring(p145.tag)))
    end

    return nil
end

return t2
